#define main historical_cli_main
#include "../pathfinder-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <algorithm>
const int SENT=-12345;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<int>load(const char*name){std::ifstream io(name,std::ios::binary|std::ios::ate);size_t n=io.tellg();std::vector<int>v(n/4);io.seekg(0);io.read((char*)v.data(),n);return v;}
struct Case{int cols,rows,h;std::vector<int>data;int*w,*a,*b,*dbg;};
void reset(Case&c){std::vector<int>v(c.cols+2,SENT);std::copy(c.data.begin(),c.data.begin()+c.cols,v.begin()+1);ck(cudaMemcpy(c.a,v.data(),v.size()*4,cudaMemcpyDefault));ck(cudaMemcpy(c.b,v.data(),v.size()*4,cudaMemcpyDefault));std::vector<int>d(16386,0);d.front()=d.back()=SENT;ck(cudaMemcpy(c.dbg,d.data(),d.size()*4,cudaMemcpyDefault));ck(cudaDeviceSynchronize());}
std::pair<int*,int*>pipeline(Case&c){int*s=c.a,*d=c.b;for(int t=0;t<c.rows-1;t+=c.h){int it=std::min(c.h,c.rows-t-1);pathfinder<<<c.rows*c.cols/250,250>>>(c.w+1,s+1,d+1,c.dbg+1,it,1,c.h,c.cols,t);std::swap(s,d);}ck(cudaDeviceSynchronize());return{s,d};}
void capture(std::vector<int>&out,int*p,size_t n){size_t pos=out.size();out.resize(pos+n);ck(cudaMemcpy(out.data()+pos,p,n*4,cudaMemcpyDefault));}
int main(){auto f=load(PF_FIXTURE),oracle=load(PF_ORACLE);size_t pos=1;std::vector<Case>cases;for(int ci=0;ci<f[0];ci++){Case c;c.cols=f[pos++];c.rows=f[pos++];c.h=f[pos++];c.data.assign(f.begin()+pos,f.begin()+pos+c.cols*c.rows);pos+=c.cols*c.rows;std::vector<int>w(2+c.cols*(c.rows-1),SENT);std::copy(c.data.begin()+c.cols,c.data.end(),w.begin()+1);ck(cudaMalloc(&c.w,w.size()*4));ck(cudaMemcpy(c.w,w.data(),w.size()*4,cudaMemcpyDefault));ck(cudaMalloc(&c.a,(c.cols+2)*4));ck(cudaMalloc(&c.b,(c.cols+2)*4));ck(cudaMalloc(&c.dbg,16386*4));cases.push_back(c);}for(auto&c:cases){reset(c);pipeline(c);}for(int trial=1;trial<=5;trial++){auto payload=f;double total=0;std::vector<double>times;for(auto&c:cases){reset(c);auto start=std::chrono::steady_clock::now();auto buffers=pipeline(c);double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();total+=t;times.push_back(t);capture(payload,c.w,2+c.cols*(c.rows-1));capture(payload,buffers.first,c.cols+2);capture(payload,buffers.second,c.cols+2);capture(payload,c.dbg,16386);}bool ok=std::equal(oracle.begin(),oracle.end(),payload.begin()+f.size());std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*4);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"timing_region\":\"sum5_source_ghostzone_pipelines_context_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":60,\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),ok?0:1);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}return 0;}
